let pausedScope=null;
$('pauseViewing').onclick=()=>{if(pausedScope){pausedScope=null;$('pauseViewing').textContent='Pause view';$('pauseViewing').setAttribute('aria-pressed','false');scopeStatus('Live viewing resumed.');}else{pausedScope=Object.assign(new LiveScope(scope.fs),{...scope,raw:scope.raw.slice(),view:scope.view.slice(),detected:[...scope.detected],waveforms:scope.waveforms.map(a=>a.slice())});$('pauseViewing').textContent='Resume view';$('pauseViewing').setAttribute('aria-pressed','true');scopeStatus('Viewing paused. Acquisition and sound continue; zoom controls remain available.');}};
'use strict';
function scopeStatus(text,error=false){$('scopeStatus').textContent=text;$('scopeStatus').classList.toggle('error',error);}
function scales(){scope.window=Math.max(.01,Math.min(10,Number($('xScale').value)||3));scope.range=Math.max(10,Math.min(5000,Number($('yScale').value)||250));$('xScale').value=Number(scope.window.toFixed(3));$('yScale').value=Number(scope.range.toFixed(1));}
$('xIn').onclick=()=>{$('xScale').value=scope.window/2;scales();};$('xOut').onclick=()=>{$('xScale').value=scope.window*2;scales();};$('yIn').onclick=()=>{$('yScale').value=scope.range/2;scales();};$('yOut').onclick=()=>{$('yScale').value=scope.range*2;scales();};$('xScale').onchange=scales;$('yScale').onchange=scales;$('yAuto').onclick=()=>{scope.autoRange();$('yScale').value=scope.range;};
function setThreshold(value){try{scope.setThreshold(value);$('threshold').value=scope.threshold.toFixed(1);scopeStatus('Manual threshold set. Detection uses the displayed signal; raw recording is unaffected.');}catch(err){scopeStatus(err.message,true);}}
$('threshold').onchange=()=>setThreshold(Number($('threshold').value));$('thresholdFactor').onchange=()=>{scope.factor=Math.max(2,Math.min(10,Number($('thresholdFactor').value)||4.5));$('thresholdFactor').value=scope.factor;};$('autoThresholdNow').onclick=()=>{if(scope.n<scope.fs*.1){scopeStatus('Collect at least 0.1 seconds of data before estimating the threshold.',true);return;}scope.estimateThreshold();$('threshold').value=scope.threshold.toFixed(1);scopeStatus('Threshold estimated once at '+scope.threshold.toFixed(1)+' µV. It stays fixed until you change or estimate it again.');};
function applyFilter(){if($('highpass').value.trim()===''||$('lowpass').value.trim()===''){scopeStatus('Enter both cutoff values; 0 disables a cutoff.');return;}try{scope.setFilter({highpass:Number($('highpass').value),lowpass:Number($('lowpass').value)});if(pausedScope)pausedScope.setFilter(scope.settings);$('threshold').value=scope.threshold.toFixed(1);scopeStatus('Filter updated. Waveforms and detection reset; raw recording continues unchanged.');}catch(err){scopeStatus(err.message,true);}}
for(const id of ['highpass','lowpass'])$(id).addEventListener('input',()=>{$('filterPreset').value='custom';applyFilter();});$('filterPreset').onchange=()=>{const mode=$('filterPreset').value,presets={spikes:[300,6000],raw:[0,0],lfp:[1,200]};if(presets[mode]){[$('highpass').value,$('lowpass').value]=presets[mode];applyFilter();}else document.querySelector('.scopeSettings').open=true;};
$('unitToggle').onclick=()=>{$('unitInset').hidden=!$('unitInset').hidden;if(!$('unitInset').hidden&&typeof placeWaveformWindow==='function')placeWaveformWindow();};$('closeUnit').onclick=()=>{$('unitInset').hidden=true;};
function voltageAtPointer(e){const r=trace.getBoundingClientRect(),y=(e.clientY-r.top)/r.height*trace.height;return(scope.range-(y-20)/(trace.height-48)*2*scope.range);}
let draggingThreshold=false;trace.addEventListener('pointerdown',e=>{const voltage=voltageAtPointer(e),r=trace.getBoundingClientRect(),tolerance=scope.range*2*12/r.height;if(e.shiftKey||Math.abs(voltage-scope.threshold)<tolerance){draggingThreshold=true;trace.setPointerCapture(e.pointerId);setThreshold(Math.round(voltage));}});trace.addEventListener('pointermove',e=>{if(draggingThreshold)setThreshold(Math.round(voltageAtPointer(e)));});trace.addEventListener('pointerup',()=>draggingThreshold=false);trace.addEventListener('pointercancel',()=>draggingThreshold=false);
trace.addEventListener('wheel',e=>{e.preventDefault();const factor=e.deltaY<0?.8:1.25;if(e.shiftKey)$('yScale').value=scope.range*factor;else $('xScale').value=scope.window*factor;scales();},{passive:false});
let unitSpan=4,unitRange=250,unitCenter=1;
function unitScales(){unitSpan=Math.max(.2,Math.min(4,Number($('unitXScale').value)||4));unitRange=Math.max(10,Math.min(2000,Number($('unitYScale').value)||250));unitCenter=Math.max(-1+unitSpan/2,Math.min(3-unitSpan/2,unitCenter));$('unitXScale').value=Number(unitSpan.toFixed(2));$('unitYScale').value=Number(unitRange.toFixed(1));}
$('unitXIn').onclick=()=>{unitCenter=0;$('unitXScale').value=unitSpan/2;unitScales();};$('unitXOut').onclick=()=>{$('unitXScale').value=unitSpan*2;unitScales();};$('unitYIn').onclick=()=>{$('unitYScale').value=unitRange/2;unitScales();};$('unitYOut').onclick=()=>{$('unitYScale').value=unitRange*2;unitScales();};$('unitXScale').onchange=unitScales;$('unitYScale').onchange=unitScales;$('unitFit').onclick=()=>{let peak=50;for(const a of (pausedScope||scope).waveforms)for(const value of a)peak=Math.max(peak,Math.abs(value));$('unitXScale').value=4;$('unitYScale').value=Math.ceil(peak*1.15/25)*25;unitCenter=1;unitScales();};
$('unitClear').onclick=()=>{scope.waveforms.length=0;if(pausedScope)pausedScope.waveforms.length=0;scopeStatus('Waveform view cleared. New spikes will appear as they are detected.');};
const unitCanvas=$('unitWaveform');unitCanvas.addEventListener('wheel',e=>{e.preventDefault();e.stopPropagation();const factor=e.deltaY<0?.8:1.25;if(e.shiftKey)$('unitYScale').value=unitRange*factor;else{const r=unitCanvas.getBoundingClientRect(),fraction=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),anchor=unitCenter+(fraction-.5)*unitSpan,next=Math.max(.2,Math.min(4,unitSpan*factor));unitCenter=anchor-(fraction-.5)*next;$('unitXScale').value=next;}unitScales();},{passive:false});let unitDrag=null;unitCanvas.addEventListener('pointerdown',e=>{unitDrag={x:e.clientX,center:unitCenter};unitCanvas.setPointerCapture(e.pointerId);});unitCanvas.addEventListener('pointermove',e=>{if(!unitDrag)return;unitCenter=unitDrag.center-(e.clientX-unitDrag.x)/unitCanvas.getBoundingClientRect().width*unitSpan;unitScales();});unitCanvas.addEventListener('pointerup',()=>unitDrag=null);unitCanvas.addEventListener('pointercancel',()=>unitDrag=null);
function drawUnit(){if($('unitInset').hidden)return;const c=unitCanvas,box=c.getBoundingClientRect();const rw=Math.max(1,Math.round(box.width)),rh=Math.max(1,Math.round(box.height));if(c.width!==rw)c.width=rw;if(c.height!==rh)c.height=rh;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.fillStyle='#07131e';ctx.fillRect(0,0,w,h);const snippets=(pausedScope||scope).waveforms,lo=unitCenter-unitSpan/2,hi=lo+unitSpan,y=v=>17+(unitRange-v)/(2*unitRange)*(h-36),x=ms=>24+(ms-lo)/unitSpan*(w-35);ctx.strokeStyle='#243c48';ctx.beginPath();ctx.moveTo(24,y(0));ctx.lineTo(w-11,y(0));ctx.stroke();ctx.save();ctx.beginPath();ctx.rect(24,17,w-35,h-36);ctx.clip();
  for(const waveform of snippets){ctx.strokeStyle='#5bd9ba30';ctx.lineWidth=.7;ctx.beginPath();for(let i=0;i<80;i++)i?ctx.lineTo(x((i-20)/20),y(waveform[i])):ctx.moveTo(x(-1),y(waveform[i]));ctx.stroke();}
  if(snippets.length){ctx.strokeStyle='#ffbb8d';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<80;i++){const mean=snippets.reduce((s,a)=>s+a[i],0)/snippets.length;i?ctx.lineTo(x((i-20)/20),y(mean)):ctx.moveTo(x(-1),y(mean));}ctx.stroke();}ctx.restore();
  ctx.fillStyle='#a0b3c1';ctx.font='9px system-ui';ctx.fillText(lo.toFixed(1)+' ms',18,h-3);ctx.fillText(hi.toFixed(1)+' ms',w-47,h-3);ctx.fillText('±'+unitRange.toFixed(0)+' µV',3,14);ctx.fillText(snippets.length?'last '+snippets.length+' · mean':'Waiting for spikes',85,14);
}
unitScales();
function drawTrace(){const box=trace.getBoundingClientRect(),rw=Math.max(1,Math.round(box.width)),rh=Math.max(1,Math.round(box.height));if(trace.width!==rw)trace.width=rw;if(trace.height!==rh)trace.height=rh;const displayScope=pausedScope?{...pausedScope,window:scope.window,range:scope.range,threshold:scope.threshold}:scope;const w=trace.width,h=trace.height,left=52,right=15,top=20,bottom=28,pw=w-left-right,ph=h-top-bottom;tc.fillStyle='#07131e';tc.fillRect(0,0,w,h);const y=v=>top+(displayScope.range-v)/(2*displayScope.range)*ph;tc.font='12px ui-monospace';tc.textAlign='right';tc.fillStyle='#8aa5b6';tc.strokeStyle='#1e3442';tc.lineWidth=1;
  for(let i=0;i<=4;i++){const value=displayScope.range-i*displayScope.range/2;tc.beginPath();tc.moveTo(left,y(value));tc.lineTo(w-right,y(value));tc.stroke();tc.fillText(Number(value.toFixed(1)),left-8,y(value)+4);}for(let i=0;i<=4;i++){const x=left+i*pw/4;tc.beginPath();tc.moveTo(x,top);tc.lineTo(x,h-bottom);tc.stroke();tc.fillText(i===4?(pausedScope?'paused':'now'):(displayScope.window*(i/4-1)).toFixed(displayScope.window<.1?3:2)+' s',Math.min(w-right,x+22),h-7);}
  const samples=Math.round(displayScope.window*displayScope.fs),first=displayScope.n-samples;tc.save();tc.beginPath();tc.rect(left,top,pw,ph);tc.clip();tc.strokeStyle='#81e6c8';tc.lineWidth=1;tc.beginPath();
  if(samples<=pw){let started=false;for(let i=Math.max(first,0);i<displayScope.n;i++){const x=left+(i-first)/samples*pw,v=displayScope.view[i%displayScope.capacity];if(started)tc.lineTo(x,y(v));else{tc.moveTo(x,y(v));started=true;}}}
  else for(let pixel=0;pixel<pw;pixel++){const begin=Math.max(0,first+Math.floor(pixel/pw*samples)),end=first+Math.floor((pixel+1)/pw*samples);if(begin>=end)continue;let lo=Infinity,hi=-Infinity;for(let i=begin;i<end;i++){const value=displayScope.view[i%displayScope.capacity];lo=Math.min(lo,value);hi=Math.max(hi,value);}tc.moveTo(left+pixel,y(lo));tc.lineTo(left+pixel,y(hi));}tc.stroke();
  tc.strokeStyle='#ffad83';tc.lineWidth=1.4;tc.setLineDash([7,5]);tc.beginPath();tc.moveTo(left,y(displayScope.threshold));tc.lineTo(w-right,y(displayScope.threshold));tc.stroke();tc.setLineDash([]);tc.fillStyle='#ffd0b6';tc.textAlign='left';tc.fillText('Threshold '+displayScope.threshold.toFixed(1)+' µV',left+8,y(displayScope.threshold)-6);
  tc.fillStyle='#ffbd91';for(const t of displayScope.detected){const x=left+(t*displayScope.fs-first)/samples*pw;if(x>=left&&x<=w-right){tc.beginPath();tc.arc(x,top+5,2,0,Math.PI*2);tc.fill();}}tc.restore();drawUnit();
}
scales();
